 "content": "def transform(grid):
    """Extend a 7-colored horizontal rail rightward with color 1 where interrupted."""
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        if 7 in row:
            # Extend a 7 rail across the remaining cells to the right in color 1.
            last = max(c for c, value in enumerate(row) if value == 7)
            for c in range(last + 1, len(row)):
                out[r][c] = 1
    return out
